// WindowHandle — Gtk.WindowHandle
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles windowhandle with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface WindowHandleProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Widget, from Gtk.WindowHandle */
  child?: ReactNode
}

export function WindowHandle({ className, children }: WindowHandleProps) {
  return (
    <div className={cn("pt-[3px]", "min-h-0", "[filter:opacity(0.5)]", "transition-[filter]", "duration-200", "ease-[ease-out]", "bg-[image:unset]", "bg-repeat", className)}>
      {children}
    </div>
  )
}
